const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'015760':'한국전력','036460':'한국가스공사','071320':'지역난방공사','018670':'SK가스','017940':'E1','005090':'SGC에너지','047050':'포스코인터내셔널','004690':'삼천리','017390':'서울가스','034590':'인천도시가스','001120':'LX인터내셔널'};
const badge=(label,value)=>`<span class="direction ${value}">${label} ${value}</span>`;
async function load(){const r=await fetch('/api/impact');if(!r.ok)throw Error('영향 자료 읽기 실패');const e=await r.json(),m=e.macro;
const detail=(p,type,code)=>{const x=p[type];return `${badge('↑',x.up)} ${badge('↓',x.down)}<details><summary>세부 영향 · 근거</summary><p><b>영업:</b> ${esc(x.operating)}</p><p><b>금융손익:</b> ${esc(x.financial)}</p><p><b>현금흐름:</b> ${esc(x.cashflow)}</p><p><b>시차:</b> ${esc(x.lag)}</p><p><b>조건:</b> ${esc(x.condition)}</p><div class="macro-sources">${p.sourceIds.map(id=>{const s=e.sources[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`;}).join(' · ')}</div><p><a href="/analysis?indicator=${type==='fx'?'usdkrw':'kr3y'}&stock=${code}">주가 시차 비교 →</a></p></details>`;};
document.getElementById('macro-comparison').innerHTML='<div class="table-wrap"><table><thead><tr><th>종목</th><th>원/달러 상승·하락</th><th>국내 조달금리 상승·하락</th></tr></thead><tbody>'+Object.entries(m.profiles).map(([code,p])=>`<tr><td><b>${esc(names[code])}</b><br><small>${code}</small></td><td>${detail(p,'fx',code)}</td><td>${detail(p,'rate',code)}</td></tr>`).join('')+'</tbody></table></div><p><small>'+esc(m.policy)+' 미국 10년·AA− 회사채는 대용지표로 개별 차입금리와 다릅니다. 각 차트의 상세 설명을 확인하세요.</small></p>';
document.getElementById('commodity-review').innerHTML='<div class="macro-notes">'+m.commodityReview.map(c=>`<article class="macro-note"><h3>${esc(c.name)}</h3><b>${esc(c.decision)}</b><p>${esc(c.text)}</p></article>`).join('')+'</div>';
}load().catch(e=>{document.getElementById('macro-comparison').textContent=e.message;});
